//! bench-only arm over the incumbent's prebuilt llama.cpp (build 11671).
//!
//! composes `libloading` (dlopen) with bindgen's dynamic-loading `LlamaApi`; nothing llama is
//! compiled. the pinned binary is the one llama-server loads, so numbers from this arm and the
//! server arm come from one artifact. [`load`] refuses any other build before a symbol is resolved.

// generated by bindgen from llama-headers/llama.h; regenerate with `regen_bindings`
#[allow(
    clippy::all,
    clippy::pedantic,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unsafe_op_in_unsafe_fn
)]
pub mod bindings;

use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use libloading::Library;
use sha2::{Digest, Sha256};
use thiserror::Error;

pub use bindings::LlamaApi;

pub const DEFAULT_LIB_DIR: &str = "/Users/brianbruggeman/.hermes/tools/llamacpp-metal-11671-darwin-arm64/";
pub const LIB_DIR_ENV: &str = "LLAMA_LIB_DIR";
pub const LLAMA_LIB_FILE: &str = "libllama.0.7.0.dylib";
pub const COMMON_LIB_FILE: &str = "libllama-common.0.dylib";
pub const PINNED_SHA256: &str = "d54034a90777fb94ce2b8c6638b71a7cde7beb29ed7e160c0622ca894f36cabc";
pub const PINNED_BUILD_NUMBER: i32 = 11671;

const HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";
const BUILD_NUMBER_SYMBOL: &[u8] = b"LLAMA_BUILD_NUMBER\0";

#[derive(Debug, Error)]
pub enum LoadError {
    #[error("cannot read {path}: {source}")]
    Io { path: PathBuf, source: io::Error },
    #[error("sha256 mismatch for {path}: expected {expected}, actual {actual}")]
    ShaMismatch { path: PathBuf, expected: String, actual: String },
    #[error("llama build number mismatch: expected {expected}, actual {actual}")]
    BuildNumberMismatch { expected: i32, actual: i32 },
    #[error("cannot open {path}: {source}")]
    Open { path: PathBuf, source: libloading::Error },
    #[error("symbol LLAMA_BUILD_NUMBER missing from {path}: {source}")]
    BuildSymbol { path: PathBuf, source: libloading::Error },
    #[error("cannot resolve llama api from {path}: {source}")]
    Resolve { path: PathBuf, source: libloading::Error },
}

/// what the gate observed; goes in the scoreboard's `binary_sha256` and `llama_build` columns.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GateReport {
    pub sha256: String,
    pub build_number: i32,
}

pub struct LlamaLib {
    pub api: LlamaApi,
    pub report: GateReport,
}

/// `$LLAMA_LIB_DIR` or the default install dir.
#[must_use]
pub fn lib_dir_from_env() -> PathBuf {
    env::var_os(LIB_DIR_ENV).map_or_else(|| PathBuf::from(DEFAULT_LIB_DIR), PathBuf::from)
}

/// sha256 hex of the file's bytes.
///
/// # Errors
/// [`LoadError::Io`] when the file cannot be read.
pub fn sha256_hex(path: &Path) -> Result<String, LoadError> {
    let bytes = fs::read(path).map_err(|source| LoadError::Io { path: path.to_path_buf(), source })?;
    let digits = Sha256::digest(&bytes)
        .iter()
        .flat_map(|byte| [byte >> 4, byte & 0x0f])
        .map(|nibble| char::from(HEX_DIGITS[usize::from(nibble)]))
        .collect();
    Ok(digits)
}

/// # Errors
/// [`LoadError::ShaMismatch`] naming expected and actual.
pub fn check_sha(path: &Path, actual: &str, expected: &str) -> Result<(), LoadError> {
    if actual == expected {
        return Ok(());
    }
    Err(LoadError::ShaMismatch {
        path: path.to_path_buf(),
        expected: expected.to_owned(),
        actual: actual.to_owned(),
    })
}

/// # Errors
/// [`LoadError::BuildNumberMismatch`] naming expected and actual.
pub fn check_build_number(actual: i32, expected: i32) -> Result<(), LoadError> {
    if actual == expected {
        return Ok(());
    }
    Err(LoadError::BuildNumberMismatch { expected, actual })
}

/// reads the `LLAMA_BUILD_NUMBER` data symbol from a libllama-common dylib.
///
/// # Errors
/// open or symbol-resolution failure.
pub fn read_build_number(common_lib: &Path) -> Result<i32, LoadError> {
    // safety: libllama-common has no unsound initializers; the sha gate already vouches for libllama
    let library = unsafe { Library::new(common_lib) }
        .map_err(|source| LoadError::Open { path: common_lib.to_path_buf(), source })?;
    // safety: the symbol is a C `int` data object, so the symbol address is a readable `*const i32`
    let symbol = unsafe { library.get::<*const i32>(BUILD_NUMBER_SYMBOL) }
        .map_err(|source| LoadError::BuildSymbol { path: common_lib.to_path_buf(), source })?;
    // safety: see above; the library stays loaded for this read
    Ok(unsafe { **symbol })
}

/// runs both gates against `dir` without resolving any llama symbol.
///
/// # Errors
/// any gate failure.
pub fn verify_pinned(dir: &Path) -> Result<GateReport, LoadError> {
    let llama_path = dir.join(LLAMA_LIB_FILE);
    let sha256 = sha256_hex(&llama_path)?;
    check_sha(&llama_path, &sha256, PINNED_SHA256)?;
    let build_number = read_build_number(&dir.join(COMMON_LIB_FILE))?;
    check_build_number(build_number, PINNED_BUILD_NUMBER)?;
    Ok(GateReport { sha256, build_number })
}

/// gates, then dlopens libllama and resolves every allowlisted symbol.
///
/// # Errors
/// any gate failure, or a missing library or symbol.
pub fn load(dir: &Path) -> Result<LlamaLib, LoadError> {
    let report = verify_pinned(dir)?;
    let path = dir.join(LLAMA_LIB_FILE);
    // safety: sha256 equals the pinned build, so the bindings' layouts match this binary
    let api = unsafe { LlamaApi::new(&path) }.map_err(|source| LoadError::Resolve { path, source })?;
    Ok(LlamaLib { api, report })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pinned_dir() -> PathBuf {
        lib_dir_from_env()
    }

    #[test]
    fn gate_accepts_the_pinned_build() {
        let report = verify_pinned(&pinned_dir()).expect("pinned install must pass both gates");
        assert_eq!(report.sha256, PINNED_SHA256);
        assert_eq!(report.build_number, PINNED_BUILD_NUMBER);
        eprintln!("read LLAMA_BUILD_NUMBER={}", report.build_number);
    }

    #[test]
    fn load_resolves_every_symbol_of_the_pinned_build() {
        let lib = load(&pinned_dir()).expect("pinned install must load");
        assert_eq!(lib.report.build_number, PINNED_BUILD_NUMBER);
    }

    #[test]
    fn byte_altered_copy_is_rejected_with_sha_mismatch() {
        let scratch = tempfile::tempdir().expect("tempdir");
        let altered = scratch.path().join(LLAMA_LIB_FILE);
        let mut bytes = fs::read(pinned_dir().join(LLAMA_LIB_FILE)).expect("read real libllama");
        bytes[4096] ^= 0xff;
        fs::write(&altered, bytes).expect("write altered copy");
        let actual = sha256_hex(&altered).expect("hash altered copy");
        let error = check_sha(&altered, &actual, PINNED_SHA256).expect_err("altered bytes must not pass");
        assert!(matches!(&error, LoadError::ShaMismatch { expected, actual: seen, .. }
            if expected == PINNED_SHA256 && *seen == actual));
        let alt_dir_error = verify_pinned(scratch.path()).expect_err("altered dir must not pass");
        assert!(matches!(alt_dir_error, LoadError::ShaMismatch { .. }), "{alt_dir_error}");
    }

    #[test]
    fn build_number_other_than_pinned_is_rejected() {
        let error = check_build_number(11670, PINNED_BUILD_NUMBER).expect_err("11670 must not pass");
        assert!(matches!(error, LoadError::BuildNumberMismatch { expected: 11671, actual: 11670 }));
        assert!(error.to_string().contains("expected 11671, actual 11670"));
    }
}
